namespace ghidra.app.plugin.core.calltree;






using docking.widgets.tree;
using generic.theme;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.exception;
using ghidra.util.task;

public class DeadEndNode : CallNode {

	private static readonly Icon DEAD_END_ICON = new GIcon("icon.plugin.calltree.node.dead.end");
	private static readonly Icon CALL_REFERENCE_ICON = createIcon(DEAD_END_ICON, true);
	private static readonly Icon NON_CALL_REFERENCE_ICON = createIcon(DEAD_END_ICON, false);

	private Reference reference;
	private string name;

	private Program program;

	DeadEndNode(Program program, Reference reference, CallTreeOptions callTreeOptions) : base(callTreeOptions)
    {
		this.program = program;
		this.reference = reference;
		this.isCallReference = reference.getReferenceType().isCall();
	}

	/* @Override */
	public int loadAll(TaskMonitor monitor)
    {
		return 1; // this node cannot be opened
	}

	/* @Override */
	CallNode recreate() {
		return new DeadEndNode(program, reference, callTreeOptions);
	}

	/* @Override */
	public Function getRemoteFunction() {
		return null; // no function--dead end
	}

	/* @Override */
	public Address getSourceAddress() {
		return reference.getFromAddress();
	}

	public Address getRemoteAddress() {
		return reference.getToAddress();
	}

	/* @Override */
	public Icon getIcon(bool expanded) {
		return isCallReference ? CALL_REFERENCE_ICON : NON_CALL_REFERENCE_ICON;
	}

	/* @Override */
	public string getName() {
		if (name == null) {
			Address toAddress = reference.getToAddress();
			SymbolTable symbolTable = program.getSymbolTable();
			Symbol symbol = symbolTable.getPrimarySymbol(toAddress);
			if (symbol != null) {
				name = symbol.getName();
			}
			else {
				name = toAddress.toString();
			}
		}
		return name;
	}

	/* @Override */
	public bool isLeaf() {
		return true;
	}

	/* @Override */
	public ProgramLocation getLocation() {
		return new ProgramLocation(program, reference.getToAddress());
	}

	/* @Override */
	public List<GTreeNode> generateChildren(TaskMonitor monitor)
    {
		return new();
	}
}
